package com.example.tilecommerce.controller;
import com.example.tilecommerce.dto.OrderDtos.*;import com.example.tilecommerce.entity.*;import com.example.tilecommerce.service.*;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/orders") @RequiredArgsConstructor public class OrderController {private final OrderService orders;private final InvoiceService invoices;@PostMapping("/checkout") public CustomerOrder checkout(@Valid @RequestBody CheckoutRequest r){return orders.checkout(r);}@GetMapping("/mine") public List<CustomerOrder> mine(){return orders.myOrders();}@GetMapping("/{id}") public CustomerOrder get(@PathVariable Long id){return orders.get(id);}@PostMapping("/{id}/payment") public Payment pay(@PathVariable Long id,@Valid @RequestBody PaymentSubmitRequest r){return orders.submitPayment(id,r.paymentReference());}@PostMapping("/{id}/verify-payment") @PreAuthorize("hasAnyRole('SHOP_OWNER','SUPER_ADMIN')") public Payment verify(@PathVariable Long id){return orders.verifyPayment(id);}@PatchMapping("/{id}/status") @PreAuthorize("hasAnyRole('SHOP_OWNER','SUPER_ADMIN')") public CustomerOrder status(@PathVariable Long id,@Valid @RequestBody StatusRequest r){return orders.status(id,r.status());}@GetMapping("/{id}/invoice") public Invoice invoice(@PathVariable Long id){return invoices.get(id);}@GetMapping("/{id}/invoice/pdf") public ResponseEntity<byte[]> pdf(@PathVariable Long id){return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=invoice-"+id+".pdf").body(invoices.pdf(id));}}
